@page "/book-appointment"
@rendermode InteractiveServer
@using sv_1eb0ad4146344f8db3d732d00d6bfcf3.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book a Medical Appointment</h3>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="appointment">

    @* ───── STEP 1 ───── *@
    <div class="card mb-4">
        <div class="card-header"><strong>Step 1 — Patient Information</strong></div>
        <div class="card-body">
            <div class="mb-3">
                <label class="form-label">Patient Name</label>
                <InputText class="form-control" @bind-Value="Model.PatientName" />
                <ValidationMessage For="() => Model.PatientName" />
            </div>

            <div class="mb-3">
                <label class="form-label">Email</label>
                <InputText class="form-control" @bind-Value="Model.Email" />
                <ValidationMessage For="() => Model.Email" />
                @if (_serverErrors.ContainsKey(nameof(Model.Email)))
                {
                    <div class="validation-message">@_serverErrors[nameof(Model.Email)]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label">Phone</label>
                <InputText class="form-control" @bind-Value="Model.Phone" />
                <ValidationMessage For="() => Model.Phone" />
            </div>

            <div class="mb-3">
                <label class="form-label">Insurance Provider</label>
                <InputSelect class="form-select" @bind-Value="Model.InsuranceProvider">
                    <option value="">-- Select --</option>
                    <option value="Aetna">Aetna</option>
                    <option value="BlueCross">BlueCross</option>
                    <option value="Cigna">Cigna</option>
                    <option value="UnitedHealth">UnitedHealth</option>
                    <option value="None">None</option>
                </InputSelect>
                <ValidationMessage For="() => Model.InsuranceProvider" />
            </div>

            @if (!_step2Visible)
            {
                <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                    Next
                </button>
            }
        </div>
    </div>

    @* ───── STEP 2 ───── *@
    @if (_step2Visible)
    {
        <div class="card mb-4">
            <div class="card-header"><strong>Step 2 — Appointment Details</strong></div>
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label">Preferred Doctor</label>
                    <InputSelect class="form-select" @bind-Value="Model.PreferredDoctor"
                                 @bind-Value:after="OnDoctorOrDateChanged">
                        <option value="">-- Select --</option>
                        @foreach (var doc in _doctors)
                        {
                            <option value="@doc">@doc</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.PreferredDoctor" />
                    @if (_serverErrors.ContainsKey(nameof(Model.PreferredDoctor)))
                    {
                        <div class="validation-message">@_serverErrors[nameof(Model.PreferredDoctor)]</div>
                    }
                </div>

                <div class="mb-3">
                    <label class="form-label">Date</label>
                    <InputDate class="form-control" @bind-Value="Model.AppointmentDate"
                               @bind-Value:after="OnDoctorOrDateChanged" />
                    <ValidationMessage For="() => Model.AppointmentDate" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Time Slot</label>
                    <InputSelect class="form-select" @bind-Value="Model.TimeSlot">
                        <option value="">-- Select --</option>
                        @foreach (var slot in _availableSlots)
                        {
                            <option value="@slot">@slot</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.TimeSlot" />
                    @if (_serverErrors.ContainsKey(nameof(Model.TimeSlot)))
                    {
                        <div class="validation-message">@_serverErrors[nameof(Model.TimeSlot)]</div>
                    }
                </div>

                <div class="mb-3">
                    <label class="form-label">Reason for Visit</label>
                    <InputTextArea class="form-control" @bind-Value="Model.ReasonForVisit" rows="3" />
                    <ValidationMessage For="() => Model.ReasonForVisit" />
                </div>

                <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability"
                        disabled="@_checking">
                    @(_checking ? "Checking…" : "Check Availability")
                </button>

                @if (_validated)
                {
                    <button type="submit" class="btn btn-success">Book Appointment</button>
                }
            </div>
        </div>
    }
</EditForm>

@if (_booked)
{
    <div class="alert alert-success mt-3">
        Appointment booked successfully for <strong>@Model.PatientName</strong>
        with <strong>@Model.PreferredDoctor</strong>
        on @Model.AppointmentDate?.ToString("MMM dd, yyyy") at @Model.TimeSlot.
    </div>
}

@code {
    private AppointmentModel Model { get; set; } = new();
    private EditContext? _editContext;

    private bool _step2Visible;
    private bool _checking;
    private bool _validated;
    private bool _booked;

    private List<string> _doctors = [];
    private List<string> _availableSlots = [];
    private Dictionary<string, string> _serverErrors = new();

    protected override async Task OnInitializedAsync()
    {
        _editContext = new EditContext(Model);
        _doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        _editContext = new EditContext(Model);

        // Validate only step-1 fields
        var step1Valid =
            !string.IsNullOrWhiteSpace(Model.PatientName) &&
            !string.IsNullOrWhiteSpace(Model.Email) &&
            new System.ComponentModel.DataAnnotations.EmailAddressAttribute().IsValid(Model.Email) &&
            !string.IsNullOrWhiteSpace(Model.Phone) &&
            !string.IsNullOrWhiteSpace(Model.InsuranceProvider);

        // Trigger validation messages
        _editContext.Validate();

        if (step1Valid)
        {
            _step2Visible = true;
            _validated = false;
            _serverErrors.Clear();
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        _validated = false;
        _serverErrors.Clear();
        Model.TimeSlot = string.Empty;

        if (!string.IsNullOrEmpty(Model.PreferredDoctor) && Model.AppointmentDate.HasValue)
        {
            _availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(
                Model.PreferredDoctor, Model.AppointmentDate.Value);
        }
        else
        {
            _availableSlots = [];
        }
    }

    private async Task CheckAvailability()
    {
        _serverErrors.Clear();
        _validated = false;

        _editContext = new EditContext(Model);
        if (!_editContext.Validate())
            return;

        // Additional client-side check for future date
        if (Model.AppointmentDate.HasValue && Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            _serverErrors[nameof(Model.AppointmentDate)] = "Date must be in the future.";
            return;
        }

        _checking = true;
        try
        {
            var errors = await AppointmentSvc.ValidatePatientAsync(
                Model.Email,
                Model.InsuranceProvider,
                Model.PreferredDoctor,
                Model.TimeSlot);

            if (errors.Count > 0)
            {
                _serverErrors = errors;
            }
            else
            {
                _validated = true;
            }
        }
        finally
        {
            _checking = false;
        }
    }

    private void HandleSubmit()
    {
        if (_validated)
        {
            _booked = true;
        }
    }
}

